//! API Error Handling

use axum::{
    Json,
    http::StatusCode,
    response::{IntoResponse, Response},
};
use serde::Serialize;
use thiserror::Error;
use utoipa::ToSchema;

/// RFC 7807 Problem Details
#[derive(Debug, Serialize, ToSchema)]
pub struct ProblemDetails {
    /// A URI reference that identifies the problem type
    #[serde(rename = "type")]
    pub r#type: String,
    /// A short, human-readable summary of the problem type
    pub title: String,
    /// The HTTP status code generated by the origin server
    pub status: u16,
    /// A human-readable explanation specific to this occurrence
    pub detail: String,
    /// A URI reference that identifies the specific occurrence
    #[serde(skip_serializing_if = "Option::is_none")]
    pub instance: Option<String>,
    /// Additional extensions
    #[serde(skip_serializing_if = "Option::is_none")]
    pub extensions: Option<serde_json::Value>,
}

impl ProblemDetails {
    pub fn new(status: StatusCode, title: &str, detail: &str) -> Self {
        Self {
            r#type: format!("https://httpstatuses.com/{}", status.as_u16()),
            title: title.to_string(),
            status: status.as_u16(),
            detail: detail.to_string(),
            instance: None,
            extensions: None,
        }
    }

    pub fn with_instance(mut self, instance: &str) -> Self {
        self.instance = Some(instance.to_string());
        self
    }

    pub fn with_extension(mut self, key: &str, value: serde_json::Value) -> Self {
        let mut map = self.extensions.unwrap_or_else(|| serde_json::json!({}));
        map[key] = value;
        self.extensions = Some(map);
        self
    }
}

/// API Error types
#[derive(Debug, Error)]
pub enum ApiError {
    #[error("Unauthorized: {0}")]
    Unauthorized(String),
    #[error("Forbidden: {0}")]
    Forbidden(String),
    #[error("Not found: {0}")]
    NotFound(String),
    #[error("Bad request: {0}")]
    BadRequest(String),
    #[error("Conflict: {0}")]
    Conflict(String),
    #[error("Unprocessable entity: {0}")]
    UnprocessableEntity(String),
    #[error("Too many requests: {0}")]
    TooManyRequests(String),
    #[error("Internal server error: {0}")]
    Internal(String),
    #[error("Service unavailable: {0}")]
    ServiceUnavailable(String),
}

/// Authentication error types
#[derive(Debug, Error)]
pub enum AuthError {
    #[error("Unauthorized: {0}")]
    Unauthorized(String),
    #[error("Forbidden: {0}")]
    Forbidden(String),
    #[error("Invalid credentials")]
    InvalidCredentials,
    #[error("Token expired")]
    TokenExpired,
    #[error("Token invalid")]
    TokenInvalid,
    #[error("Token revoked")]
    TokenRevoked,
    #[error("Two-factor required")]
    TwoFactorRequired,
    #[error("Invalid two-factor code")]
    InvalidTwoFactorCode,
    #[error("Two-factor not enabled")]
    TwoFactorNotEnabled,
    #[error("Invalid backup code")]
    InvalidBackupCode,
    #[error("User not found")]
    UserNotFound,
    #[error("User disabled")]
    UserDisabled,
    #[error("User locked")]
    UserLocked,
    #[error("Session not found")]
    SessionNotFound,
    #[error("Session expired")]
    SessionExpired,
    #[error("Access token not found")]
    AccessTokenNotFound,
    #[error("Insufficient permissions: {0}")]
    InsufficientPermissions(String),
    #[error("Rate limited")]
    RateLimited,
    #[error("Internal error: {0}")]
    Internal(String),
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (status, title, detail) = match &self {
            ApiError::Unauthorized(msg) => (StatusCode::UNAUTHORIZED, "Unauthorized", msg.as_str()),
            ApiError::Forbidden(msg) => (StatusCode::FORBIDDEN, "Forbidden", msg.as_str()),
            ApiError::NotFound(msg) => (StatusCode::NOT_FOUND, "Not Found", msg.as_str()),
            ApiError::BadRequest(msg) => (StatusCode::BAD_REQUEST, "Bad Request", msg.as_str()),
            ApiError::Conflict(msg) => (StatusCode::CONFLICT, "Conflict", msg.as_str()),
            ApiError::UnprocessableEntity(msg) => (
                StatusCode::UNPROCESSABLE_ENTITY,
                "Unprocessable Entity",
                msg.as_str(),
            ),
            ApiError::TooManyRequests(msg) => (
                StatusCode::TOO_MANY_REQUESTS,
                "Too Many Requests",
                msg.as_str(),
            ),
            ApiError::Internal(msg) => (
                StatusCode::INTERNAL_SERVER_ERROR,
                "Internal Server Error",
                msg.as_str(),
            ),
            ApiError::ServiceUnavailable(msg) => (
                StatusCode::SERVICE_UNAVAILABLE,
                "Service Unavailable",
                msg.as_str(),
            ),
        };

        let problem = ProblemDetails::new(status, title, detail);
        (status, Json(problem)).into_response()
    }
}

impl IntoResponse for AuthError {
    fn into_response(self) -> Response {
        let (status, title, detail) = match &self {
            AuthError::Unauthorized(msg) => {
                (StatusCode::UNAUTHORIZED, "Unauthorized", msg.as_str())
            }
            AuthError::Forbidden(msg) => (StatusCode::FORBIDDEN, "Forbidden", msg.as_str()),
            AuthError::InvalidCredentials => (
                StatusCode::UNAUTHORIZED,
                "Invalid Credentials",
                "Invalid username or password",
            ),
            AuthError::TokenExpired => (
                StatusCode::UNAUTHORIZED,
                "Token Expired",
                "Authentication token has expired",
            ),
            AuthError::TokenInvalid => (
                StatusCode::UNAUTHORIZED,
                "Invalid Token",
                "Authentication token is invalid",
            ),
            AuthError::TokenRevoked => (
                StatusCode::UNAUTHORIZED,
                "Token Revoked",
                "Authentication token has been revoked",
            ),
            AuthError::TwoFactorRequired => (
                StatusCode::UNAUTHORIZED,
                "Two-Factor Required",
                "Two-factor authentication is required",
            ),
            AuthError::InvalidTwoFactorCode => (
                StatusCode::UNAUTHORIZED,
                "Invalid 2FA Code",
                "Invalid two-factor authentication code",
            ),
            AuthError::TwoFactorNotEnabled => (
                StatusCode::BAD_REQUEST,
                "2FA Not Enabled",
                "Two-factor authentication is not enabled",
            ),
            AuthError::InvalidBackupCode => (
                StatusCode::UNAUTHORIZED,
                "Invalid Backup Code",
                "Invalid backup code",
            ),
            AuthError::UserNotFound => (StatusCode::NOT_FOUND, "User Not Found", "User not found"),
            AuthError::UserDisabled => (
                StatusCode::FORBIDDEN,
                "User Disabled",
                "User account is disabled",
            ),
            AuthError::UserLocked => (
                StatusCode::FORBIDDEN,
                "User Locked",
                "User account is locked",
            ),
            AuthError::SessionNotFound => (
                StatusCode::UNAUTHORIZED,
                "Session Not Found",
                "Session not found",
            ),
            AuthError::SessionExpired => (
                StatusCode::UNAUTHORIZED,
                "Session Expired",
                "Session has expired",
            ),
            AuthError::AccessTokenNotFound => (
                StatusCode::UNAUTHORIZED,
                "Access Token Not Found",
                "Access token not found",
            ),
            AuthError::InsufficientPermissions(msg) => (
                StatusCode::FORBIDDEN,
                "Insufficient Permissions",
                msg.as_str(),
            ),
            AuthError::RateLimited => (
                StatusCode::TOO_MANY_REQUESTS,
                "Rate Limited",
                "Too many requests",
            ),
            AuthError::Internal(msg) => (
                StatusCode::INTERNAL_SERVER_ERROR,
                "Internal Server Error",
                msg.as_str(),
            ),
        };

        let problem = ProblemDetails::new(status, title, detail);
        (status, Json(problem)).into_response()
    }
}

impl From<anyhow::Error> for ApiError {
    fn from(err: anyhow::Error) -> Self {
        ApiError::Internal(err.to_string())
    }
}

impl From<anyhow::Error> for AuthError {
    fn from(err: anyhow::Error) -> Self {
        AuthError::Internal(err.to_string())
    }
}
